'use strict';

const POW10 = (n) => Math.pow(10, n);

function isInt(value) {
  return Number.isInteger(value);
}

function digitClass(lo, hi) {
  if (lo === hi) return String(lo);
  if (lo === 0 && hi === 9) return '[0-9]';
  return `[${lo}-${hi}]`;
}

function fixedPattern(lo, hi, width) {
  if (lo === hi) return String(lo).padStart(width, '0');

  if (lo === 0 && hi === POW10(width) - 1) {
    return width === 1 ? '[0-9]' : `[0-9]{${width}}`;
  }

  if (width === 1) return digitClass(lo, hi);

  const step = POW10(width - 1);
  const firstLo = Math.floor(lo / step);
  const firstHi = Math.floor(hi / step);

  const groups = [];
  for (let d = firstLo; d <= firstHi; d++) {
    const base = d * step;
    const subLo = d === firstLo ? lo - base : 0;
    const subHi = d === firstHi ? hi - base : step - 1;
    const sub = fixedPattern(subLo, subHi, width - 1);
    const last = groups[groups.length - 1];
    if (last && last.sub === sub && last.end === d - 1) {
      last.end = d;
    } else {
      groups.push({ start: d, end: d, sub });
    }
  }

  return groups.map((g) => digitClass(g.start, g.end) + g.sub).join('');
}

function positivePattern(lo, hi) {
  if (lo > hi) return null;
  if (lo === hi) return String(lo);

  const parts = [];
  for (let width = 1; ; width++) {
    const wLo = Math.max(lo, width === 1 ? 0 : POW10(width - 1));
    const wHi = Math.min(hi, POW10(width) - 1);
    if (wLo <= wHi) parts.push(fixedPattern(wLo, wHi, width));
    if (POW10(width) - 1 >= hi) break;
  }

  return parts.length === 1 ? parts[0] : `(?:${parts.join('|')})`;
}

function toRegexRange(min, max, options = {}) {
  if (max === undefined) {
    max = min;
  }

  min = Number(min);
  max = Number(max);

  if (!isInt(min) || !isInt(max)) {
    throw new TypeError('toRegexRange: expected integer arguments');
  }

  if (min > max) {
    [min, max] = [max, min];
  }

  const alternatives = [];

  if (min < 0) {
    const negHi = Math.min(max, -1);
    const abs = positivePattern(Math.abs(negHi), Math.abs(min));
    alternatives.push(abs === null ? '' : `-${abs}`);
  }

  if (max >= 0) {
    alternatives.push(positivePattern(Math.max(min, 0), max));
  }

  let pattern = alternatives.length === 1 ? alternatives[0] : `(?:${alternatives.join('|')})`;

  const { capture = false, anchor = false } = options;
  if (capture) {
    pattern = `(${pattern})`;
  }
  if (anchor) {
    pattern = `^${pattern}$`;
  }

  return pattern;
}

module.exports = toRegexRange;
module.exports.toRegexRange = toRegexRange;

#!/usr/bin/env node
'use strict';

const toRegexRange = require('../');

function usage() {
  return [
    'Usage: range-to-regex <min> <max> [--anchor] [--capture]',
    '       range-to-regex <min>-<max> [--anchor] [--capture]',
    '',
    'Examples:',
    '  range-to-regex 1 100',
    '  range-to-regex 1-100 --anchor',
    '  range-to-regex -10-10 --capture',
  ].join('\n');
}

function parseArgs(argv) {
  const options = { anchor: false, capture: false };
  const positional = [];

  for (const arg of argv) {
    if (arg === '--anchor') options.anchor = true;
    else if (arg === '--capture') options.capture = true;
    else if (arg === '-h' || arg === '--help') options.help = true;
    else positional.push(arg);
  }

  return { positional, options };
}

function parseRange(positional) {
  if (positional.length === 2) {
    return [positional[0], positional[1]];
  }

  if (positional.length === 1) {
    const match = positional[0].match(/^(-?\d+)\s*-\s*(-?\d+)$/);
    if (!match) return null;
    return [match[1], match[2]];
  }

  return null;
}

function main(argv) {
  const { positional, options } = parseArgs(argv);

  if (options.help || positional.length === 0) {
    process.stdout.write(usage() + '\n');
    return positional.length === 0 && !options.help ? 1 : 0;
  }

  const range = parseRange(positional);
  if (!range) {
    process.stderr.write('Error: could not parse range. Expected "<min>-<max>" or "<min> <max>".\n');
    process.stderr.write(usage() + '\n');
    return 1;
  }

  try {
    process.stdout.write(toRegexRange(range[0], range[1], options) + '\n');
    return 0;
  } catch (err) {
    process.stderr.write(`Error: ${err.message}\n`);
    return 1;
  }
}

if (require.main === module) {
  process.exitCode = main(process.argv.slice(2));
}

module.exports = main;

'use strict';

const assert = require('assert');
const toRegexRange = require('../');

function matches(range, n) {
  const re = new RegExp(`^(?:${toRegexRange(range[0], range[1])})$`);
  return re.test(String(n));
}

function verify(range) {
  const [min, max] = range;
  for (let n = min; n <= max; n++) {
    assert.ok(matches(range, n), `${toRegexRange(min, max)} should match ${n}`);
  }
  for (const n of [min - 1, max + 1, min - 10, max + 10]) {
    assert.ok(!matches(range, n), `${toRegexRange(min, max)} should not match ${n}`);
  }
}

const cases = [
  [0, 0],
  [1, 9],
  [1, 10],
  [1, 100],
  [0, 100],
  [12, 34],
  [10, 99],
  [100, 999],
  [123, 4567],
  [1000, 9999],
  [1, 65535],
  [-5, 5],
  [-100, -1],
  [-100, 100],
  [-50, 50],
];

for (const range of cases) {
  verify(range);
}

assert.strictEqual(toRegexRange(1, 100), '(?:[1-9]|[1-9][0-9]|100)');
assert.strictEqual(toRegexRange(1, 9), '[1-9]');
assert.strictEqual(toRegexRange(5, 5), '5');
assert.strictEqual(toRegexRange(1, 100, { anchor: true }), '^(?:[1-9]|[1-9][0-9]|100)$');
assert.strictEqual(toRegexRange(1, 9, { capture: true }), '([1-9])');
assert.throws(() => toRegexRange(1.5, 10), TypeError);

process.stdout.write('All tests passed.\n');

import re

def digitClass(lo, hi):
    if lo == hi:
        return str(lo)
    if lo == 0 and hi == 9:
        return "[0-9]"
    return "[%d-%d]" % (lo, hi)

def fixedPattern(lo, hi, width):
    if lo == hi:
        return str(lo).rjust(width, "0")
    if lo == 0 and hi == 10**width - 1:
        return "[0-9]" if width == 1 else "[0-9]{%d}" % width
    if width == 1:
        return digitClass(lo, hi)
    step = 10 ** (width - 1)
    firstLo = lo // step
    firstHi = hi // step
    groups = []
    for d in range(firstLo, firstHi + 1):
        base = d * step
        subLo = lo - base if d == firstLo else 0
        subHi = hi - base if d == firstHi else step - 1
        sub = fixedPattern(subLo, subHi, width - 1)
        if groups and groups[-1][2] == sub and groups[-1][1] == d - 1:
            groups[-1][1] = d
        else:
            groups.append([d, d, sub])
    return "".join(digitClass(g[0], g[1]) + g[2] for g in groups)

def positivePattern(lo, hi):
    if lo > hi:
        return None
    if lo == hi:
        return str(lo)
    parts = []
    width = 1
    while True:
        wLo = max(lo, 0 if width == 1 else 10 ** (width - 1))
        wHi = min(hi, 10 ** width - 1)
        if wLo <= wHi:
            parts.append(fixedPattern(wLo, wHi, width))
        if 10 ** width - 1 >= hi:
            break
        width += 1
    return parts[0] if len(parts) == 1 else "(?:%s)" % "|".join(parts)

def toRegexRange(mn, mx, options=None):
    options = options or {}
    if mn > mx:
        mn, mx = mx, mn
    alts = []
    if mn < 0:
        negHi = min(mx, -1)
        abs_ = positivePattern(abs(negHi), abs(mn))
        alts.append("" if abs_ is None else "-" + abs_)
    if mx >= 0:
        alts.append(positivePattern(max(mn, 0), mx))
    pattern = alts[0] if len(alts) == 1 else "(?:%s)" % "|".join(alts)
    if options.get("capture"):
        pattern = "(" + pattern + ")"
    if options.get("anchor"):
        pattern = "^" + pattern + "$"
    return pattern

def verify(mn, mx):
    pat = "^(?:%s)$" % toRegexRange(mn, mx)
    rx = re.compile(pat)
    for n in range(mn, mx + 1):
        assert rx.match(str(n)), "%s should match %d" % (pat, n)
    for n in (mn - 1, mx + 1, mn - 10, mx + 10):
        assert not rx.match(str(n)), "%s should not match %d" % (pat, n)

cases = [(0,0),(1,9),(1,10),(1,100),(0,100),(12,34),(10,99),(100,999),
         (123,4567),(1000,9999),(1,65535),(-5,5),(-100,-1),(-100,100),(-50,50),
         (98,102),(999,1001),(10000,99999)]
for c in cases:
    verify(*c)

